import sys

def min_moves(a, b):
    if a % b == 0:
        return 0
    else:
        return b - (a % b)

def main():
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1

    results = []
    for _ in range(t):
        a = int(data[index])
        index += 1
        b = int(data[index])
        index += 1
        results.append(min_moves(a, b))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
